// Some portions generated by Claude

// The query editor's prefix completion: the repository's namespaces (with the configured ones the server adds to them)
// first, then the fallback list (the deployment's namespaces.fallback; the bundled list is empty) for every prefix they
// do not define. YASQE adds a PREFIX line from this list when a prefixed name is typed.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function load(fallback) {
    const registered = {};
    const fetches = [];
    const YASQE = {
        defaults: {},
        registerAutocompleter(name, init) { registered[name] = init; },
        Autocompleters: { prefixes: {
            appendPrefixIfNeeded() {},
            isValidCompletionPosition() { return true; },
            preprocessPrefixTokenForCompletion(editor, token) { return token; }
        } }
    };
    const document = {
        getElementById: id => id === 'workbench-app'
            ? { getAttribute: name => name === 'data-workbench-base-path' ? '/workbench' : null } : null
    };
    const fetch = (url, options) => {
        fetches.push({ url, credentials: options && options.credentials });
        return fallback instanceof Error ? Promise.reject(fallback)
            : Promise.resolve({ ok: true, json: () => Promise.resolve(fallback) });
    };
    const context = vm.createContext({ console, Promise, YASQE, document, fetch, window: {}, workbench: {} });
    vm.runInContext(fs.readFileSync(path.join(scripts, 'yasqeHelper.js'), 'utf8'), context, { filename: 'yasqeHelper.js' });
    return { workbench: context.workbench, registered, fetches };
}

function editor() {
    return { on() {} };
}

/** The lists the completer hands YASQE, once the fallback list has arrived (or failed). */
async function completions(helper, namespaces) {
    helper.workbench.yasqeHelper.setupCompleters(namespaces);
    const completer = helper.registered.customPrefixCompleter(editor(), 'customPrefixCompleter');
    assert.equal(completer.bulk, true);
    assert.equal(completer.async, true, 'YASQE stores each list the completer hands it');
    const lists = [];
    completer.get(null, list => lists.push(Array.from(list)));
    await new Promise(resolve => setTimeout(resolve, 0));
    return lists;
}

test('the fallback namespaces follow the repository ones, for the prefixes the repository does not define', async () => {
    const helper = load({ foaf: 'http://xmlns.com/foaf/0.1/', ex: 'urn:fallback:ex:', schema: 'http://schema.org/' });
    const lists = await completions(helper, { 'ex:': 'urn:ex:', 'bsbm:': 'urn:bsbm:' });

    assert.equal(lists.length, 2, 'the repository namespaces at once, then with the fallback list');
    assert.deepEqual(lists[0], ['ex: <urn:ex:>', 'bsbm: <urn:bsbm:>']);
    assert.deepEqual(lists[1], ['ex: <urn:ex:>', 'bsbm: <urn:bsbm:>', 'foaf: <http://xmlns.com/foaf/0.1/>',
        'schema: <http://schema.org/>']);
    assert.deepEqual(helper.fetches, [{ url: '/workbench/fallback-namespaces', credentials: 'same-origin' }]);
});

test('every editor of a page shares one request for the fallback list', async () => {
    const helper = load({ foaf: 'http://xmlns.com/foaf/0.1/' });
    await completions(helper, {});
    const lists = await completions(helper, { 'ex:': 'urn:ex:' });

    assert.deepEqual(lists[1], ['ex: <urn:ex:>', 'foaf: <http://xmlns.com/foaf/0.1/>']);
    assert.equal(helper.fetches.length, 1);
});

test('without the fallback list the editor keeps completing the repository namespaces', async () => {
    const helper = load(new Error('offline'));
    const lists = await completions(helper, { 'ex:': 'urn:ex:' });

    assert.deepEqual(lists, [['ex: <urn:ex:>']]);
});
